import React, { useState, useEffect } from "react";
import Avatar from "./Avatar";
import { useAuth } from "../context/AuthContext";
import { getRoomName, fmtTime } from "../utils/helpers";
import { getAllUsers, createRoom } from "../services/api";

export default function Sidebar({ rooms, activeRoomId, onSelectRoom, onRoomsChange, wsConnected, messages, unread = {} }) {
  const { username, signOut } = useAuth();
  const [search, setSearch]   = useState("");
  const [showModal, setShowModal] = useState(false);

  const filtered = rooms.filter((r) =>
    getRoomName(r, username).toLowerCase().includes(search.toLowerCase())
  );

  const totalUnread = Object.values(unread).reduce((a, b) => a + b, 0);

  return (
    <>
      <aside className="w-full sm:w-80 flex-shrink-0 bg-crisp-surface flex flex-col h-full">

        {/* ── Header ─────────────────────────────────────────────────────── */}
        <div className="px-4 pt-5 pb-3 border-b border-crisp-border">
          <div className="flex items-center gap-3 mb-4">
            {/* Logo */}
            <div className="w-10 h-10 bg-gradient-to-br from-crisp-accent to-crisp-accentDk
              rounded-2xl flex items-center justify-center shadow-accent-sm flex-shrink-0">
              <span className="font-mono font-bold text-white text-base">C</span>
            </div>
            <div className="flex-1 min-w-0">
              <div className="font-display font-bold text-lg text-crisp-text leading-none">Crisp</div>
              <div className="flex items-center gap-1.5 mt-1">
                <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 transition-colors
                  ${wsConnected ? "bg-crisp-green" : "bg-crisp-amber animate-pulse2"}`} />
                <span className="text-[11px] text-crisp-muted font-mono">
                  {wsConnected ? "Connected" : "Connecting…"}
                </span>
              </div>
            </div>
            <button onClick={signOut} title="Sign out"
              className="w-10 h-10 rounded-2xl bg-crisp-card border border-crisp-border
                flex items-center justify-center text-crisp-muted hover:text-crisp-sub
                active:scale-95 transition-all flex-shrink-0">
              <LogoutIcon />
            </button>
          </div>

          {/* Me pill */}
          <div className="flex items-center gap-3 bg-crisp-card border border-crisp-border/60
            rounded-2xl px-3 py-2.5">
            <Avatar name={username} size="sm" online />
            <div className="flex-1 min-w-0">
              <div className="text-sm font-display font-semibold text-crisp-text truncate">{username}</div>
              <div className="text-[11px] text-crisp-green font-mono">● Online</div>
            </div>
            {totalUnread > 0 && (
              <span className="badge animate-bounceIn">{totalUnread > 99 ? "99+" : totalUnread}</span>
            )}
          </div>
        </div>

        {/* ── Search ─────────────────────────────────────────────────────── */}
        <div className="px-4 py-3 border-b border-crisp-border/50">
          <div className="relative">
            <svg className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-crisp-muted pointer-events-none"
              fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
            </svg>
            <input
              className="input-field pl-10 !py-3 !rounded-xl"
              style={{ fontSize: "15px" }}
              placeholder="Search conversations…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
        </div>

        {/* ── Room list ──────────────────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto px-2 py-2 no-scrollbar">
          {filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
              <div className="w-12 h-12 rounded-2xl bg-crisp-card border border-crisp-border
                flex items-center justify-center text-xl opacity-40">💬</div>
              <p className="text-crisp-muted text-sm font-body text-center">
                {search ? "No results found" : "No conversations yet\nTap + to start one"}
              </p>
            </div>
          ) : (
            <div className="space-y-1">
              {filtered.map((room) => (
                <RoomItem key={room.id} room={room}
                  active={room.id === activeRoomId}
                  onClick={() => onSelectRoom(room)}
                  username={username}
                  lastMsg={(messages[room.id] || []).slice(-1)[0]}
                  unreadCount={unread[room.id] || 0}
                />
              ))}
            </div>
          )}
        </div>

        {/* ── New Chat ───────────────────────────────────────────────────── */}
        <div className="p-4 border-t border-crisp-border pb-safe">
          <button onClick={() => setShowModal(true)}
            className="w-full flex items-center justify-center gap-2.5 py-3.5 rounded-2xl
              bg-crisp-accent/10 hover:bg-crisp-accent/16 active:scale-98 active:bg-crisp-accent/20
              border border-crisp-accent/20 text-crisp-accent2 font-display font-semibold
              text-sm transition-all duration-200 select-none">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path d="M12 5v14M5 12h14"/>
            </svg>
            New Conversation
          </button>
        </div>
      </aside>

      {showModal && (
        <NewChatModal
          onClose={() => setShowModal(false)}
          onCreated={(room) => { onRoomsChange(room); setShowModal(false); onSelectRoom(room); }}
          myUsername={username}
          existingRooms={rooms}
        />
      )}
    </>
  );
}

function RoomItem({ room, active, onClick, username, lastMsg, unreadCount }) {
  const name    = getRoomName(room, username);
  const isGroup = room.isGroup || room.group;
  const preview = lastMsg
    ? `${lastMsg.senderId === username ? "You: " : ""}${lastMsg.content}`
    : "Tap to open chat";

  return (
    <div className={`room-item ${active ? "active" : ""}`} onClick={onClick}>
      <Avatar name={name} size="md" square={isGroup} />
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-2 mb-0.5">
          <span className="text-[15px] font-display font-semibold text-crisp-text truncate">{name}</span>
          {lastMsg?.timestamp && (
            <span className={`text-[11px] flex-shrink-0 font-mono
              ${unreadCount > 0 ? "text-crisp-accent2" : "text-crisp-muted"}`}>
              {fmtTime(lastMsg.timestamp)}
            </span>
          )}
        </div>
        <div className="flex items-center justify-between gap-2">
          <p className={`text-[13px] truncate font-body
            ${unreadCount > 0 ? "text-crisp-sub font-medium" : "text-crisp-muted"}`}>
            {preview}
          </p>
          {unreadCount > 0 && (
            <span className="badge flex-shrink-0 animate-bounceIn">
              {unreadCount > 99 ? "99+" : unreadCount}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

function NewChatModal({ onClose, onCreated, myUsername, existingRooms }) {
  const [type, setType]     = useState("dm");
  const [users, setUsers]   = useState([]);
  const [selected, setSel]  = useState([]);
  const [groupName, setGN]  = useState("");
  const [loading, setLoad]  = useState(false);
  const [error, setError]   = useState("");
  const [usersLoading, setUL] = useState(true);

  useEffect(() => {
    getAllUsers()
      .then(({ data }) => setUsers(data.filter((u) => u.username !== myUsername)))
      .catch(() => setError("Could not load users"))
      .finally(() => setUL(false));
  }, []);

  const toggle = (u) => {
    if (type === "dm") { setSel([u]); return; }
    setSel((prev) => prev.includes(u) ? prev.filter((x) => x !== u) : [...prev, u]);
  };

  const handleCreate = async () => {
    if (!selected.length) { setError("Select at least one user"); return; }
    if (type === "group" && !groupName.trim()) { setError("Enter a group name"); return; }
    setLoad(true); setError("");
    try {
      const body = { participantIds: [myUsername, ...selected], isGroup: type === "group",
        ...(type === "group" && { name: groupName.trim() }) };
      const { data } = await createRoom(body);
      onCreated(data);
    } catch (err) {
      const msg = err.response?.data?.error || "";
      if (msg.includes("already exists")) {
        const ex = existingRooms.find((r) => !(r.isGroup || r.group) && r.participantIds?.includes(selected[0]));
        if (ex) { onCreated(ex); return; }
      }
      setError(msg || "Failed to create room");
    } finally { setLoad(false); }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center"
      onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-crisp-surface border border-crisp-border w-full max-w-sm
        rounded-t-3xl sm:rounded-3xl shadow-2xl animate-slideUp pb-safe">

        {/* Handle bar on mobile */}
        <div className="flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-10 h-1 rounded-full bg-crisp-border2" />
        </div>

        <div className="p-5">
          <div className="flex items-center justify-between mb-5">
            <h2 className="font-display font-bold text-lg text-crisp-text">New Conversation</h2>
            <button onClick={onClose} className="w-8 h-8 rounded-xl bg-crisp-card border border-crisp-border
              flex items-center justify-center text-crisp-muted text-xl leading-none">×</button>
          </div>

          {/* Type toggle */}
          <div className="flex bg-crisp-bg rounded-2xl p-1 mb-5 border border-crisp-border gap-1">
            {["dm", "group"].map((t) => (
              <button key={t} onClick={() => { setType(t); setSel([]); }}
                className={`flex-1 py-2.5 rounded-xl font-display font-semibold text-sm transition-all
                  ${type === t ? "bg-crisp-accent text-white shadow-accent-sm" : "text-crisp-muted"}`}>
                {t === "dm" ? "💬 Direct" : "👥 Group"}
              </button>
            ))}
          </div>

          {type === "group" && (
            <div className="mb-4">
              <label className="block text-xs font-display font-semibold text-crisp-muted uppercase tracking-widest mb-2">Group Name</label>
              <input className="input-field !rounded-2xl" placeholder="Weekend Plans, Team Alpha…"
                value={groupName} onChange={(e) => setGN(e.target.value)} />
            </div>
          )}

          <label className="block text-xs font-display font-semibold text-crisp-muted uppercase tracking-widest mb-2">
            {type === "dm" ? "Select User" : "Add Members"}
          </label>
          <div className="bg-crisp-bg border border-crisp-border rounded-2xl overflow-hidden max-h-52 overflow-y-auto mb-4 no-scrollbar">
            {usersLoading ? (
              <div className="py-8 text-center">
                <div className="flex justify-center gap-1">
                  {[0,1,2].map(i => <div key={i} className="w-2 h-2 rounded-full bg-crisp-border2 animate-pulse2" style={{animationDelay:`${i*0.15}s`}} />)}
                </div>
              </div>
            ) : users.length === 0 ? (
              <div className="py-8 text-center text-crisp-muted text-sm px-4">No other users registered yet.</div>
            ) : users.map((u) => {
              const sel = selected.includes(u.username);
              return (
                <div key={u.username} onClick={() => toggle(u.username)}
                  className={`flex items-center gap-3 px-4 py-3.5 cursor-pointer transition-all active:scale-98
                    border-b border-crisp-border/40 last:border-0
                    ${sel ? "bg-crisp-accent/10" : "hover:bg-crisp-hover active:bg-crisp-hover"}`}>
                  <Avatar name={u.fullName || u.username} size="sm" />
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-display font-semibold text-crisp-text truncate">{u.fullName || u.username}</div>
                    <div className="text-xs text-crisp-muted font-mono">@{u.username}</div>
                  </div>
                  <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center
                    text-xs font-bold transition-all flex-shrink-0
                    ${sel ? "bg-crisp-accent border-crisp-accent text-white" : "border-crisp-border2"}`}>
                    {sel && "✓"}
                  </div>
                </div>
              );
            })}
          </div>

          {error && <div className="mb-4 text-red-300 text-sm bg-red-500/10 border border-red-500/20 px-3 py-2.5 rounded-xl">{error}</div>}

          <div className="flex gap-2">
            <button onClick={onClose} className="btn-ghost flex-1 !py-3.5">Cancel</button>
            <button onClick={handleCreate} disabled={loading} className="btn-primary flex-1 !py-3.5">
              {loading ? "Creating…" : "Create →"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

const LogoutIcon = () => (
  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
    <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/>
    <polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/>
  </svg>
);
